let hero = game.user.character;
if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.getFlag("vagabond-app", "paragonsaura"))?.actor;
}

if (!hero || !hero.getFlag("vagabond-app", "paragonsaura")) return;

game.system.api.rules.toggleEffect(hero, "Compendium.vagabond-app.features.Item.JTiiACptF2LnprJp");
